use serde_json::json;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut jobs = input.as_array().unwrap();
    let mut total_wait = 0;
    let mut server_time = 0;

    while jobs.len() > 0 {
        let job = jobs.pop().unwrap();
        let arrival = job["arrival"].as_i64().unwrap();
        let duration = job["duration"].as_i64().unwrap();

        if arrival <= server_time {
            server_time += duration;
        } else {
            total_wait += (server_time - arrival) as i64;
            server_time = arrival;
        }

        jobs.push(job);
    }

    total_wait
}

fn main() {
    let input = json!([{"arrival": 0, "duration": 3}, {"arrival": 1, "duration": 2}, {"arrival": 8, "duration": 1}]);
    println!("{}", solve(input));
}
